create or replace function seed_default_auto_send_rules(p_studio_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_tattoo_id uuid;
  v_photo_id  uuid;
  v_minor_id  uuid;
  v_after_id  uuid;
  v_reach_id  uuid;
begin
  -- Sage C1 fix — security definer bypasses RLS on the INSERT below, so we
  -- must authenticate the caller against p_studio_id ourselves. Without this
  -- guard, any authenticated user could seed rules into any studio.
  -- Owner/admin only: seeding defaults is a privileged action.
  if not exists (
    select 1 from studio_members
    where studio_id = p_studio_id
      and user_id = auth.uid()
      and deactivated_at is null
      and role in ('owner', 'admin')
  ) then
    raise exception 'not authorized to seed auto-send rules for studio %', p_studio_id
      using errcode = '42501';
  end if;

  -- Resolve the 5 template ids by slug. If a studio archived a default
  -- template, the corresponding rule simply isn't seeded — studios can
  -- re-seed after un-archiving.
  select id into v_tattoo_id from consent_form_templates
    where studio_id = p_studio_id and slug = 'standard-tattoo' and is_active limit 1;
  select id into v_photo_id  from consent_form_templates
    where studio_id = p_studio_id and slug = 'photo-release' and is_active limit 1;
  select id into v_minor_id  from consent_form_templates
    where studio_id = p_studio_id and slug = 'minor-consent' and is_active limit 1;
  select id into v_after_id  from consent_form_templates
    where studio_id = p_studio_id and slug = 'aftercare-ack' and is_active limit 1;
  select id into v_reach_id  from consent_form_templates
    where studio_id = p_studio_id and slug = 'reach-ink-doc' and is_active limit 1;

  -- Idempotent — ON CONFLICT (studio_id, trigger) DO NOTHING preserves any
  -- studio customizations to the defaults (e.g. they toggled one off).
  if v_tattoo_id is not null then
    insert into consent_auto_send_rules
      (studio_id, trigger, template_id, timing, timing_value, channels, is_default, enabled)
    values
      (p_studio_id, 'any_booking', v_tattoo_id, 'hours_before_session', 24, array['sms', 'email']::text[], true, true)
    on conflict (studio_id, trigger) do nothing;
